def choose_move(observation):
    wx=observation['grid_width']
    hy=observation['grid_height']
    px,py=observation['self_position']
    ox,oy=observation['opponent_position']
    obstacles=set(map(tuple,observation.get('obstacles',[])))
    resources=observation.get('resources',[])
    def dist(a,b): return abs(a[0]-b[0])+abs(a[1]-b[1])
    target=None
    min_d=9999
    for r in resources:
        d=dist((px,py),(r['x'],r['y']))
        if d<min_d: min_d=d; target=(r['x'],r['y'])
    def move_towards(tx,ty):
        dx=dy=0
        if tx>px: dx=1
        elif tx<px: dx=-1
        if ty>py: dy=1
        elif ty<py: dy=-1
        next_pos=(px+dx,py+dy)
        if 0<=next_pos[0]<wx and 0<=next_pos[1]<hy and next_pos not in obstacles:
            return [dx,dy]
        if 0<=px+dx<wx and 0<=py+dy<hy and (px+dx,py+dy) not in obstacles:
            return [dx,dy]
        if 0<=px+dy<wx and 0<=py+dy<hy and (px+dy,py+dy) not in obstacles:
            return [0,dy]
        if 0<=px+dx<wx and 0<=py+dx<hy and (px+dx,py+dx) not in obstacles:
            return [dx,0]
        return [0,0]
    if target:
        return move_towards(target[0],target[1])
    # no resources, move to center as fallback
    center_x,center_y=wx//2,hy//2
    return move_towards(center_x,center_y)
